update public.problems set hidden_tests = '[{"label":"Self-equality trivial","inputJson":"{\"equations\":[\"a==a\"]}","expectedJson":"true"},{"label":"Self-inequality contradiction","inputJson":"{\"equations\":[\"a!=a\"]}","expectedJson":"false"},{"label":"Long transitive chain ok","inputJson":"{\"equations\":[\"a==b\",\"b==c\",\"c==d\",\"d==e\",\"a==e\"]}","expectedJson":"true"},{"label":"Chain then opposite negation","inputJson":"{\"equations\":[\"a==b\",\"b==c\",\"c==d\",\"a!=d\"]}","expectedJson":"false"},{"label":"Many independent inequalities","inputJson":"{\"equations\":[\"a!=b\",\"b!=c\",\"c!=d\",\"d!=e\"]}","expectedJson":"true"},{"label":"Inequality then equality order","inputJson":"{\"equations\":[\"a!=b\",\"b==c\",\"c==a\"]}","expectedJson":"false"},{"label":"Single equality","inputJson":"{\"equations\":[\"a==b\"]}","expectedJson":"true"},{"label":"Single inequality","inputJson":"{\"equations\":[\"a!=b\"]}","expectedJson":"true"},{"label":"Same pair both directions","inputJson":"{\"equations\":[\"a==b\",\"b==a\"]}","expectedJson":"true"},{"label":"Two independent groups","inputJson":"{\"equations\":[\"a==b\",\"c==d\",\"e==f\",\"a!=c\"]}","expectedJson":"true"},{"label":"Many ineqs no equalities","inputJson":"{\"equations\":[\"a!=b\",\"a!=c\",\"a!=d\",\"a!=e\"]}","expectedJson":"true"},{"label":"Big star of equalities","inputJson":"{\"equations\":[\"a==b\",\"a==c\",\"a==d\",\"a==e\",\"b==e\"]}","expectedJson":"true"}]'::jsonb where slug = 'satisfiability-of-equality-equations';
