update public.problems set hidden_tests = '[{"label":"Both empty","inputJson":"{\"s\":\"\",\"t\":\"\"}","expectedJson":"true"},{"label":"Equal strings","inputJson":"{\"s\":\"abc\",\"t\":\"abc\"}","expectedJson":"true"},{"label":"Longer than t","inputJson":"{\"s\":\"abcd\",\"t\":\"abc\"}","expectedJson":"false"},{"label":"Single match","inputJson":"{\"s\":\"b\",\"t\":\"abcde\"}","expectedJson":"true"},{"label":"Repeated chars in t","inputJson":"{\"s\":\"aaa\",\"t\":\"ababab\"}","expectedJson":"true"},{"label":"Duplicates need order","inputJson":"{\"s\":\"abb\",\"t\":\"acbcb\"}","expectedJson":"true"},{"label":"Empty t with empty s","inputJson":"{\"s\":\"\",\"t\":\"abcdef\"}","expectedJson":"true"},{"label":"Single mismatch","inputJson":"{\"s\":\"z\",\"t\":\"abcdef\"}","expectedJson":"false"},{"label":"Subsequence at end","inputJson":"{\"s\":\"def\",\"t\":\"abcdef\"}","expectedJson":"true"},{"label":"Reverse order fails","inputJson":"{\"s\":\"cba\",\"t\":\"abcdef\"}","expectedJson":"false"}]'::jsonb where slug = 'is-subsequence';
