update public.problems set hidden_tests = '[{"label":"No cookies at all","inputJson":"{\"g\":[5,6,7],\"s\":[]}","expectedJson":"0"},{"label":"One child many cookies","inputJson":"{\"g\":[3],\"s\":[1,2,4,5]}","expectedJson":"1"},{"label":"All children exactly matched","inputJson":"{\"g\":[1,2,3],\"s\":[3,2,1]}","expectedJson":"3"},{"label":"All cookies too small","inputJson":"{\"g\":[10,11,12],\"s\":[1,2,3]}","expectedJson":"0"},{"label":"Large values","inputJson":"{\"g\":[2147483647,1],\"s\":[2147483647]}","expectedJson":"1"},{"label":"Duplicates unordered","inputJson":"{\"g\":[2,2,2,2],\"s\":[1,2,1,2]}","expectedJson":"2"},{"label":"Equal counts perfect","inputJson":"{\"g\":[1,1,1],\"s\":[1,1,1]}","expectedJson":"3"},{"label":"Reverse sorted both","inputJson":"{\"g\":[5,4,3,2,1],\"s\":[10,8,6,4,2]}","expectedJson":"5"},{"label":"Some satisfied","inputJson":"{\"g\":[1,2,5,6],\"s\":[3,3,4]}","expectedJson":"2"},{"label":"Single child single cookie","inputJson":"{\"g\":[7],\"s\":[7]}","expectedJson":"1"},{"label":"Single child cookie too small","inputJson":"{\"g\":[7],\"s\":[6]}","expectedJson":"0"}]'::jsonb where slug = 'assign-cookies';
